void SceneObject::SetLPosition(const Float4 & pos) {
	Transform.SetPosition(pos);
}

void SceneObject::SetLRotation(const Float3 & axis, float deg) {
	Transform.SetRotation(Float4{ axis, deg });
}

void SceneObject::SetLScale(const Float4 & scale) {
	Transform.SetScale(scale);
}

