Float4 SceneObject::GetLPosition() {	
	//SceneObject::GetLPosition() : This should not really be called publicly. If done, think about it, is this really what you want?
	return Transform.GetPosition();
}

Float4 SceneObject::GetLScale() {
	//SceneObject::GetLScale() : This should not really be called publicly. If done, think about it, is this really what you want?
