void SceneObject::Draw(Microsoft::WRL::ComPtr<ID3D11DeviceContext> context) {}
void SceneObject::Animate(InputArgs & args) {}
void SceneObject::Control(InputArgs & args) {}

Float4x4 SceneObject::GetModelMatrix() {
	return Transform.GetModelMatrix() * GetParentModelMatrix();
}

Float4x4 SceneObject::GetParentModelMatrix() {
	if(Parent) {
		return Parent->GetModelMatrix();
	}
	return Float4x4::identity;
}

void SceneObject::SetFromLua(LuaContext & ctx) {
	AObject::SetFromLua(ctx);
}

